#include "../../../src/resident/domains/commerce/liquidation/private_shop_liquidation.hpp"
#include "resident/domains/local_economy/local_economy_internal.hpp"
namespace {
struct EstateFixture:Fixture {
    PrivateShopLiquidationCatalog policies;PrivateShopLiquidationState mandates;FamilyDeathState deaths;
    std::optional<FamilyDeathOrigin> owner_death;StableId shop_id;TaskDeliveredDeathNoticeRead notice_read;
    EstateFixture(){common.state().metadata.scenario_id="estate.component";auto opened=open_private_shop(common,economy,state,context(),meeting(),quote());check(opened.ok,"original shop opening");shop_id=opened.value.shop_id;auto original_session=common.next_id("interaction");check(original_session.ok,"original interaction session allocation");conversations.interactions.front().id=original_session.value;PrivateShopExecutorPolicy policy;policy.id="executor";policy.premises_id="stall";policy.executor_actor_id="lessor";policy.proprietor_actor_id="owner";policy.executor_role_id="lessor.role";policy.proprietor_role_id="owner.role";RoleDefinition owner_role;owner_role.id="owner.role";owner_role.initial_actor="owner";owner_role.place_id="market";owner_role.dialogue_id="owner.executor";common_catalog->roles.insert(owner_role.id,owner_role);common.state().roles.insert(owner_role.id,{"owner",true,{}});DialogueDefinition appointment;appointment.id="owner.executor";appointment.context_role="owner.role";appointment.entry="agree";DialogueNode yes;yes.id="agree";yes.kind="say";yes.speaker="$provider";appointment.nodes.push_back(yes);dialogue.dialogues.push_back(appointment);policy.proprietor_dialogue_id="owner.executor";policy.executor_dialogue_id="lease";policy.proprietor_appointment_node_id=policy.executor_acceptance_node_id="agree";policies.policies.insert(policy.id,policy);}
    PrivateShopLiquidationContext authorization(){return {common,*common_catalog,state,catalog,mandates,policies,dialogue,deaths,[this](const StableId& actor)->Outcome<std::optional<FamilyDeathOrigin>>{return {true,actor=="owner"?owner_death:std::nullopt,{}};},notice_read};}
    Outcome<PrivateShopExecutorReceipt> apply(const PrivateShopExecutorQuote& q){auto x=authorization();local_economy_detail::PhaseSavepoint outer(common);if(!outer.token().ok)return {false,{},outer.token().error};local_economy_detail::CandidateStateGuard<PrivateShopLiquidationState> guard(mandates);auto result=apply_private_shop_executor_in_candidate(common,mandates,x,meeting(),activities,q);if(!result.ok)return result;auto committed=outer.commit();if(!committed.ok)return {false,{},committed.error};guard.commit();return result;}
    Outcome<PrivateShopExecutorQuote> appoint(){return preview_private_shop_executor(authorization(),meeting(),activities,"owner",PrivateShopAppointExecutor{shop_id,"executor"});}
    void death(){auto id=common.next_id("military");check(id.ok&&common.append_fact({id.value,"military_casualties","military"}).ok,"actual death source header");owner_death=FamilyDeathOrigin{"owner",id.value,"battle.original",common.tick()};auto* actor=common.state().actors.find("owner");actor->alive=actor->available=false;actor->hp=0;}
};
void executorship_sources(){
    EstateFixture f;const auto money=encode_common_state(f.common.state());auto q=f.appoint();check(q.ok,"real provider say offers executor acceptance");check(compare_boundary(money,encode_common_state(f.common.state())).exact(),"mandate preview read only");auto accepted=f.apply(q.value);check(accepted.ok&&f.mandates.mandates.size()==1&&f.mandates.acceptances.size()==1,"separate original appointment and executor acceptance");check(f.common.wallet("owner.wallet")->balance==1800&&f.common.wallet("lessor.wallet")->balance==900&&f.common.wallet(f.state.shops.find(f.shop_id)->wallet_id)->balance==300,"appointment transfers no assets");check(validate_private_shop_liquidation_authorizations(f.authorization()).ok,"actual two-fact ledger validates");check(!f.appoint().ok,"second appointment cannot reuse old consent");
    auto original=f.mandates;const auto acceptance_id=accepted.value.acceptance_fact_id;f.mandates.acceptances.find(acceptance_id)->executor_actor_id="owner";check(!validate_private_shop_liquidation_authorizations(f.authorization()).ok,"forged executor acceptance rejected");f.mandates=original;
    f.mandates.mandates.find(accepted.value.mandate_fact_id)->agreement.role_id="owner.role";check(!validate_private_shop_liquidation_authorizations(f.authorization()).ok,"same-place other actor role cannot supply executor declaration");f.mandates=original;
    f.mandates.mandates.find(accepted.value.mandate_fact_id)->agreement.session_id="interaction:999999";check(!validate_private_shop_liquidation_authorizations(f.authorization()).ok,"future or fabricated session cannot support accepted mandate");f.mandates=original;
    auto* m=f.mandates.mandates.find(accepted.value.mandate_fact_id);m->return_wallet_id="lessor.wallet";check(!validate_private_shop_liquidation_authorizations(f.authorization()).ok,"executor cannot redirect estate cash");f.mandates=original;
    const auto a=*f.mandates.acceptances.find(acceptance_id);f.mandates.acceptances.erase(acceptance_id);f.mandates.acceptances.insert("wrong.key",a);check(!validate_private_shop_liquidation_authorizations(f.authorization()).ok,"acceptance table key cannot replace source identity");f.mandates=original;
    auto revoked=preview_private_shop_executor(f.authorization(),f.meeting(),f.activities,"owner",PrivateShopRevokeExecutor{accepted.value.mandate_fact_id,"revoke"});check(revoked.ok&&f.apply(revoked.value).ok,"living proprietor explicitly revokes");check(!f.apply(revoked.value).ok,"new request cannot repeat old revocation");auto replacement=f.appoint();check(replacement.ok&&f.apply(replacement.value).ok,"new mandate requires a fresh real decision after revocation");
}
void death_order_and_late_rollback(){
    EstateFixture f;auto q=f.appoint();check(q.ok,"appointment quote");auto saved=encode_common_state(f.common.state());auto state_before=f.mandates;f.common.state().next_instance_id=std::numeric_limits<Integer>::max()-1;q=f.appoint();check(q.ok,"high remaining ID quote");saved=encode_common_state(f.common.state());auto failed=f.apply(q.value);check(!failed.ok&&compare_boundary(saved,encode_common_state(f.common.state())).exact()&&f.mandates.mandates.empty()&&f.mandates.acceptances.empty(),"second fact ID failure rolls back Common and both authorization tables");
    EstateFixture g;auto first=g.appoint();check(first.ok,"living initial appointment");auto done=g.apply(first.value);check(done.ok,"write appointment before death");g.death();check(validate_private_shop_liquidation_authorizations(g.authorization()).ok,"later real death preserves prior authorization before registration");check(!g.appoint().ok,"dead proprietor cannot sign another mandate");auto revoke=preview_private_shop_executor(g.authorization(),g.meeting(),g.activities,"lessor",PrivateShopRevokeExecutor{done.value.mandate_fact_id,"withdraw"});check(!revoke.ok,"executor cannot abandon frozen mandate after proprietor death");
    // 将真实原因头调到接受之前，即使相同tick且尚无Family登记也应拒绝。
    auto before=g.common.state().facts;const auto cause=g.owner_death->casualty_fact_id;auto cause_record=*g.common.state().facts.find(cause);auto mandate=*g.common.state().facts.find(done.value.mandate_fact_id);auto acceptance=*g.common.state().facts.find(done.value.acceptance_fact_id);g.common.state().facts.erase(cause);g.common.state().facts.erase(mandate.id);g.common.state().facts.erase(acceptance.id);g.common.state().facts.insert(cause,cause_record);g.common.state().facts.insert(mandate.id,mandate);g.common.state().facts.insert(acceptance.id,acceptance);check(!validate_private_shop_liquidation_authorizations(g.authorization()).ok,"same-tick death before acceptance cannot hide behind later registration");g.common.state().facts=before;
    // 使用具名变量持有借口，不能让访问器指向上一句返回的临时Context。
    auto context=g.authorization();PrivateShopEstateCancellationAccess stable(context);PrivateShopEstateCancellationRequest request{g.shop_id,"unknown","owner","lessor",done.value.mandate_fact_id,"unknown"};check(!stable.private_shop_estate_cancellation(request).ok,"unknown original order gives no estate cancellation authority");
}

// 独立来源夹具不运行Task付款；只核S5必须收到的精确原订单/死亡/实交文书截面。
void bounded_cancellation_sources(){
    EstateFixture f;auto q=f.appoint();check(q.ok,"source appointment quote");auto mandate=f.apply(q.value);check(mandate.ok,"source accepted mandate");
    auto add=[&](const StableId& prefix,const StableId& kind,const StableId& domain){auto id=f.common.next_id(prefix);check(id.ok&&f.common.append_fact({id.value,kind,domain}).ok,"original source header");return id.value;};
    PrivateShopOrderRecord order;order.id=add("private_shop_order","private_shop_order_issued","private_shops");order.status="accepted";order.task_id="task.original";order.acceptance_fact_id=add("task_shop_order_accepted","task_shop_order_accepted","task_shop_orders");order.binding_fact_id=add("private_shop_order_bound","private_shop_order_bound","private_shops");order.terms.order_id=order.id;order.terms.shop_id=f.shop_id;order.terms.proprietor_actor_id="owner";order.terms.shop_wallet_id=f.state.shops.find(f.shop_id)->wallet_id;order.terms.stock_inventory_id=f.state.shops.find(f.shop_id)->inventory_id;order.terms.accepted_tick=0;f.state.orders.orders.insert(order.id,order);f.state.orders.bindings.insert(order.binding_fact_id,{order.binding_fact_id,order.id,order.task_id,order.acceptance_fact_id,0});
    f.death();auto source=f.authorization();auto death=record_family_death(f.common,f.deaths,source.death_origin,"owner");check(death.ok,"actual Family death writer after source projection");
    DeliveredTaskDeathNotice notice;notice.scenario_id=f.common.state().metadata.scenario_id;notice.death_fact_id=death.value;notice.decedent_actor_id="owner";notice.sender_actor_id="witness";notice.recipient_actor_id="lessor";notice.task_id="task.notice";notice.source_lot_id="lot.notice";notice.binding_fact_id=add("task_death_notice_bound","task_death_notice_bound","tasks");notice.handoff_fact_id=add("task_message_handoff","task_message_handoff","tasks");
    f.notice_read=[&](const StableId& observer,const StableId& binding)->Outcome<std::optional<DeliveredTaskDeathNotice>>{if(observer!=notice.recipient_actor_id||binding!=notice.binding_fact_id)return {true,std::nullopt,{}};auto current=notice;current.identity=f.common.state().identity;return {true,std::move(current),{}};};
    PrivateShopEstateCancellationRequest request{f.shop_id,order.id,"owner","lessor",mandate.value.mandate_fact_id,notice.binding_fact_id};auto context=f.authorization();PrivateShopEstateCancellationAccess read(context);auto authority=read.private_shop_estate_cancellation(request);check(authority.ok&&authority.value.return_wallet_id=="owner.wallet"&&authority.value.request.executor_actor_id=="lessor","true death and received notice permit only original owner assets");
    auto receipt=add("task_shop_order_settled","task_shop_order_settled","task_shop_orders");check(read.private_shop_estate_cancellation_before_settlement(request,receipt,0).ok,"same-tick original received notice precedes actual settlement");
    auto wrong=request;wrong.order_id="some.other.order";check(!read.private_shop_estate_cancellation(wrong).ok,"different order not authorized");wrong=request;wrong.executor_actor_id="owner";check(!read.private_shop_estate_cancellation(wrong).ok,"executor substitution rejected");
    auto real=notice.handoff_fact_id;notice.handoff_fact_id=add("task_message_handoff","task_message_handoff","tasks");check(!read.private_shop_estate_cancellation_before_settlement(request,receipt,0).ok,"same-tick later delivery cannot authorize earlier cancellation");notice.handoff_fact_id=real;
    check(!read.private_shop_estate_cancellation_before_settlement(request,mandate.value.mandate_fact_id,0).ok,"arbitrary Common header cannot stand for Task settlement");notice.death_fact_id="other.death";check(!read.private_shop_estate_cancellation(request).ok,"notice of another death does not transfer authority");
}
}
